(() => { const send = WebSocket.prototype.send; window.__sent = 0;
  WebSocket.prototype.send = function (d) { if (this.readyState === 1) { window.__appWs = this; window.__sent++; } return send.call(this, d); };
  return true; })()

new Promise((done) => {
  const app = window.__appWs;
  if (!app) return done('no app socket');
  const probe = new WebSocket(app.url);
  probe.onmessage = (e) => {
    const msg = JSON.parse(e.data);
    if (msg.op !== 'snapshot') return;
    probe.close();
    app.onmessage({ data: e.data });
    app.onmessage({ data: JSON.stringify({ op: 'event', sessionId: 's1a20dfdd8786', seq: 1000, event: { type: 'turn_started' } }) });
    done('injected');
  };
})

